  }

  var totalArea = 0;
  final list = <List<int>>[];
  counts.forEach((key, value) {
    final parts = key.split('@');
    list.add([int.parse(parts[0]), int.parse(parts[1]), value]);
    totalArea += value;
  });

  list.sort((a, b) {
